using RevitMCP.Core;
using S=RevitMCP.Core.CadWallGeometry.Segment;
int checks=0;void Check(bool ok,string label){if(!ok)throw new Exception(label);Console.WriteLine("PASS "+label);checks++;}
List<CadWallGeometry.Run> Find(List<S> ls,List<S>? os=null)=>CadWallGeometry.Find(ls,os??new(),2,3000,50,1000);
var straight=new List<S>{new(0,0,2000,0),new(2000,200,0,200)};
var a=Find(straight);Check(a.Count==1&&a[0].Width==200&&a[0].Axis.Length==2000,"Reversed line and 200 mm width");
var split=new List<S>{new(0,0,1000,0),new(0,200,1000,200),new(2000,0,4000,0),new(2000,200,4000,200)};
Check(Find(split).Count==2,"No opening evidence: do not bridge");
a=Find(split,new(){new(1000,100,2000,100)});Check(a.Count==1&&a[0].Bridges==1&&a[0].Axis.Length==4000,"Opening evidence produces continuous wall");
Check(Find(split,new(){new(1000,500,2000,500)}).Count==2,"Unrelated nearby opening does not bridge");
Check(Find(split,new(){new(1400,100,1600,100)}).Count==2,"Partial opening evidence does not bridge");
Check(Find(new(){new(0,0,1000,0),new(0,200,1000,200),new(5000,0,6000,0),new(5000,200,6000,200)},new(){new(1000,100,5000,100)}).Count==2,"Gap limit enforced");
var multi=Find(new(){new(0,0,2000,0),new(0,200,2000,200),new(0,400,2000,400)});Check(multi.Count==2&&multi.All(x=>x.Width==200),"No pairing through intervening line");
a=Find(straight.Concat(straight).ToList());Check(a.Count==1,"Duplicate CAD lines deduplicated");
a=Find(new(){new(0,0,1000,1000),new(-100,100,900,1100)});Check(a.Count==1&&Math.Abs(a[0].Width-Math.Sqrt(20000))<0.001,"Diagonal width");
Check(CadWallGeometry.Overlaps(Find(straight)[0],new S(500,100,1500,100),200,2),"Existing wall overlap");
Check(!CadWallGeometry.Overlaps(Find(straight)[0],new S(2100,100,3000,100),200,2),"Adjacent nonoverlap");
Check(Find(new(){new(0,0,2000,0)}).Count==0,"Single line cannot infer thickness");
Console.WriteLine($"{checks} geometry checks passed");
var cad=new CadWallGeometry.Run{U=1,V=0,N=0,A=0,B=1000,Width=100};
CadLiningPlacement.Reference Ref(long id,double y,double a=0,double b=1000)=>new(){Id=id,Width=350,Axis=new S(a,y,b,y)};
var positive=CadLiningPlacement.Resolve(cad,104,new[]{Ref(1,325)},1000,2);
Check(positive.Reason==null&&positive.Run.N==2&&positive.InteriorPlane==-50,"104 mm lining grows +4 mm only toward positive reference");
var negative=CadLiningPlacement.Resolve(cad,104,new[]{Ref(2,-325)},1000,2);
Check(negative.Run.N==-2&&negative.InteriorPlane==50,"Negative side keeps interior face fixed");
Check(CadLiningPlacement.Resolve(cad,104,new[]{Ref(1,325),Ref(2,-325)},1000,2).Reason=="AmbiguousReferenceSide","Opposite reference sides rejected");
Check(CadLiningPlacement.Resolve(cad,104,Array.Empty<CadLiningPlacement.Reference>(),1000,2).Reason=="NoAdjacentReferenceWall","Internal run without reference skipped");
Check(CadLiningPlacement.Resolve(cad,104,new[]{Ref(1,325,0,600),Ref(2,325,0,600)},1000,2).Reason!=null,"Overlapping references do not double-count coverage");
Check(CadLiningPlacement.Resolve(cad,104,new[]{Ref(1,325,0,500),Ref(2,325,500,1000)},1000,2).Reason==null,"Split reference coverage supported");
Check(CadLiningPlacement.Resolve(cad,90,new[]{Ref(1,325)},1000,2).Reason=="LiningNarrowerThanCad","Narrower type rejected");
Console.WriteLine($"{checks} total geometry checks passed");
